import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { PagoLayout } from '../models/pago.layout.model';
import { UtilsService } from '../services/utils.service';

@Injectable({
    providedIn: 'any'
})
export class PagoLayoutService extends SuperService<PagoLayout> {
    protected override model: string = "pagos_layoutes";
    protected override columns: (keyof PagoLayout)[] = [
        'id',
        'numero_movimientos',
        'monto_total',
        'hash_archivo',
        'nombre_archivo_registro',
        'ruta_archivo_registro',
        'status_aplicacion',
        'fecha_proceso_terminado',
        'nombre_usuario',
        'created_at',
        'updated_at',
        'usuario_id',
        'deleted_at',
    ];

    constructor(
        private utils: UtilsService,
        injector: Injector
    ) {
        super(injector)
    }

    /**
     * Verifica si un archivo Excel ya ha sido subido previamente,
     * comparando su hash SHA-256 con registros existentes.
     *
     * @param file - El archivo Excel a verificar.
     * @returns Una promesa que resuelve a `true` si el archivo ya fue subido,
     *          o `false` si no se encuentra registro del mismo.
     */
    public async yaSeSubioExcel(file: File): Promise<boolean> {
        const hash = await this.utils.calculateFileHash(file);
        return !!(await this.first({ hash_archivo: hash, deleted_at: null }));
    }


}